// Pseudocode: per-tenant watermark advancement and late event routing
class TenantWindowManager {
  constructor() {
    this.watermark = -Infinity;
    this.windows = new Map();
  }

  onEvent(tenantId, event) {
    const isLate = event.timestamp < this.watermark;
    if (isLate) {
      this.routeToDeadLetterQueue(tenantId, event);
    } else {
      this.mergeIntoActiveWindow(tenantId, event);
    }
  }
}
```

